    #[test]
    fn tool_result_coalesces_into_following_user_message() {
        let items = vec![
            Item::AssistantMessage {
                content: vec![ContentPart::ToolUse {
                    call_id: "tu_1".to_owned(),
                    name: "ping".to_owned(),
                    args: json!({}),
                }],
                agent: None,
            },
            Item::ToolResult {
                call_id: "tu_1".to_owned(),
                content: vec![text("pong")],
            },
            Item::UserMessage {
                content: vec![text("now what?")],
            },
        ];
        let out = translate_messages(&items);
        let arr = out.messages.as_array().unwrap();
        assert_eq!(arr.len(), 2, "must not produce consecutive user turns");
        assert_eq!(arr[0]["role"], "assistant");
        assert_eq!(arr[1]["role"], "user");
        let blocks = arr[1]["content"].as_array().unwrap();
        assert_eq!(blocks.len(), 2);
        assert_eq!(
            blocks[0]["type"], "tool_result",
            "tool_result precedes text"
        );
        assert_eq!(blocks[0]["tool_use_id"], "tu_1");
        assert_eq!(blocks[1]["type"], "text");
        assert_eq!(blocks[1]["text"], "now what?");
    }

    #[test]
    fn tool_result_emits_tool_role() {
        let items = vec![Item::ToolResult {
            call_id: "c1".to_owned(),
            content: vec![text("ok")],
        }];
        let out = to_chat_messages(&items);
        assert_eq!(
            out,
            json!([{
                "role": "tool",
                "tool_call_id": "c1",
                "content": "ok",
            }])
        );
    }

    #[test]
    fn tool_result_emits_function_call_output_item() {
        let items = vec![Item::ToolResult {
            call_id: "c1".to_owned(),
            content: vec![text("42")],
        }];
        let out = to_responses_input(&items);
        assert_eq!(out[0]["type"], "function_call_output");
        assert_eq!(out[0]["call_id"], "c1");
        assert_eq!(out[0]["output"], "42");
    }
}

